if(m.in_reply_to&&/^<[^<>\s]+>$/.test(m.in_reply_to))headers.push('In-Reply-To: '+m.in_reply_to);
if(refs.length)headers.push('References: '+[...new Set(refs)].slice(-20).join(' '));
