const raw=Buffer.from(headers.join('\r\n')+'\r\n\r\n'+body).toString('base64url');
return [{json:{message_id:m.id,mime_message_id:messageId,send_body:{raw,...(m.gmail_thread_id?{threadId:m.gmail_thread_id}:{})}}}];

